do $$ declare f text; begin select pg_get_functiondef(p.oid) into f from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='revise_production_plan' and pg_get_function_identity_arguments(p.oid)='p_production_batch_id uuid, p_recipe_version_id uuid, p_additional_ingredients jsonb, p_permanent_recipe_change boolean'; if f is null then raise exception 'revise_production_plan not found'; end if; f:=replace(f,'values(v_selected,v_ing,v_qty,v_unit,v_seq,''Added from production plan'')','values(v_selected,v_ing,(v_qty*v_expected/v_plan),v_unit,v_seq,''Added from production plan'')'); f:=replace(f,'values(b.id,v_new,v_ing,v_qty*(v_plan/v_expected),v_unit)','values(b.id,v_new,v_ing,v_qty,v_unit)'); execute f; end $$;
